/**
 * Job-title families. `match` phrases detect the family from the title (or the
 * first line of a job description). Titles per language are what profiles say.
 * German titles include both gendered forms because LinkedIn does not support
 * wildcards.
 */
const T = (id, match, en, de, pl) => ({ id, match, titles: { en, de, pl } });

